'use strict';
/* Engineering extensions use the existing authenticated local API and reviewed edits. */
const E6={tab:'catalog',info:null,page:null,query:'',offset:0,picked:new Set(),task:null,report:null,policy:{roles:['engineering'],check_level:'error',catalog_required:false,stock_required:false,qualification_required:false,market:'IN',freshness_hours:24},build:null,virtual:false,vstart:0,vfocus:0,req:0};
titles.engineering=['Library & engineering control','Reuse with provenance. Approve a specific context. Plan before purchasing.'];
const eng6=(op,body={})=>api('engineering/'+op,{variant:S.variant,...body});
const pretty6=x=>JSON.stringify(x,null,2);
const field6=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${esc(label)}</span><input name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${extra}></label>`;
const area6=(label,name,value,rows=8)=>`<label class="field"><span>${esc(label)}</span><textarea name="${esc(name)}" rows="${rows}" spellcheck="false">${esc(typeof value==='string'?value:pretty6(value))}</textarea></label>`;
const button6=(act,label,extra='')=>`<button type="button" class="small" data-act="${act}" ${extra}>${label}</button>`;
const json6=x=>`<details class="eng-json"><summary>Complete structured report / provenance</summary><pre>${esc(pretty6(x))}</pre></details>`;
const state6=(state,tip='')=>`<span class="eng-state ${/blocked|error|mismatch|shortfall|at risk|not_approved|invalid|revoked/i.test(state)?'risk':/warn|nrnd|estimate|stale|expired|deprecated|review/i.test(state)?'warn':/observed|matched|approved|current|preferred|passed/i.test(state)?'good':'unknown'}" title="${esc(tip)}">${esc(state)}</span>`;
function report6(report,title='Report ready'){E6.report={data:report,title,variant:S.variant,revision:S.data?.revision};render();toast(title);}
function table6(headers,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">No entries.</td></tr>`}</tbody></table></div>`;}
function componentSelect6(name='component'){return `<label class="field"><span>Component in ${esc(S.variant)}</span><select name="${name}">${(S.data?.rows||[]).map(r=>`<option value="${esc(r.id)}">${esc(r.ref+' · '+(r.fields.Value||'')+' · '+(r.fields.Footprint||'No footprint'))}</option>`).join('')}</select></label>`;}
function reportPanel6(){const r=E6.report;if(!r)return '';return `<section class="panel"><div class="panel-title"><h2>${esc(r.title)}</h2>${button6('engDownloadReport','Save report JSON')}${button6('engClearReport','Dismiss')}</div><div class="panel-body">${r.revision!==S.data?.revision||r.variant!==S.variant?'<div class="notice warning">Workspace/variant changed after this report. Rerun before relying on it.</div>':''}${r.data.status?state6(r.data.status):''}${r.data.notice?`<p class="fine">${esc(r.data.notice)}</p>`:''}${renderReport6(r.data)}${json6(r.data)}</div></section>`;}
function renderReport6(r){
 if(r.schema==='wayricad-build-result-1')return `<p><b>${r.demands.length} demand lines · ${r.orders.length} planned orders</b> · Known cost: ${esc(pretty6(r.known_cost_by_currency))}</p>`+table6(['Build','MPN','Required','Inventory','Purchases','Shortfall','State'],r.demands.map(x=>`<tr><td>${esc(x.build)}</td><td>${esc(x.mpn)}</td><td>${x.required}</td><td>${x.inventory_used||0}</td><td>${x.purchased_allocated||0}</td><td>${x.shortfall||0}</td><td>${state6(x.status)}</td></tr>`))+`<h3>Issues requiring review</h3>`+table6(['Severity','Scope','Finding'],r.issues.map(x=>`<tr><td>${state6(x.severity)}</td><td>${esc(x.scope)}</td><td class="wrap">${esc(x.message)}</td></tr>`));
 if(r.schema==='wayricad-review-context-1')return `<p class="fine">Input fingerprint: <code>${esc(r.input_hash)}</code><br>Required roles still missing: ${esc(r.missing_roles?.join(', ')||'None')}</p><div class="row">${button6('engDecision','Record decision…')}${button6('engAccounts','Manage local reviewers')}</div>`+table6(['Severity','Finding','Scope','Action'],(r.issues||[]).map(x=>`<tr><td>${state6(x.severity)}</td><td class="wrap">${esc(x.message)}</td><td>${esc(x.reference)}</td><td>${x.severity==='error'?'Not waivable':button6('engWaiver','Review waiver…',`data-target="${esc(x.id)}"`)}</td></tr>`))+table6(['Reviewer','Role','Kind','Status','Reason'],(r.decisions||[]).map(x=>`<tr><td>${esc(x.reviewer)}</td><td>${esc(x.role)}</td><td>${esc(x.kind)}</td><td>${state6(x.status)}</td><td class="wrap">${esc(x.reason)}</td></tr>`));
 if(r.schema==='wayricad-catalog-health-1')return `<p>${r.assessed} / ${r.total} catalog identities assessed · ${r.all_matches?'all matches':'this page'} · ${esc(pretty6(r.counts))}. Dated observations, not a live query.</p>`+table6(['Internal PN','MPN','Lifecycle','Stock','State'],r.items.slice(0,200).map(x=>`<tr><td>${esc(x.internal_pn)}</td><td>${esc(x.mpn)}</td><td>${state6(x.health.lifecycle,x.health.lifecycle_labels.join(', '))}</td><td>${state6(x.health.low_stock?'LOW STOCK < '+x.health.low_stock_threshold:x.health.stock.status)}</td><td>${state6(x.health.state,x.health.tooltip)}</td></tr>`));
 if(r.issues)return table6(['Severity','Finding'],r.issues.map(x=>`<tr><td>${state6(x.severity||'unknown')}</td><td class="wrap">${esc(x.message||x)}</td></tr>`));
 return '';
}
function renderEngineering(){
 const tabs=[['catalog','Local catalog'],['reuse','Recommend & reuse'],['mass','Mass suggestions'],['variants','BOM-only variants'],['qualify','Land patterns & pins'],['reviews','Controlled reviews'],['purchasing','Multi-build planning'],['validation','Host & performance']];
 let content=`<div class="eng-tabs" role="tablist" aria-label="Engineering tools">${tabs.map(([id,label])=>`<button role="tab" aria-selected="${E6.tab===id}" data-act="engTab" data-tab="${id}" class="${E6.tab===id?'active':''}">${label}</button>`).join('')}</div><div class="eng-librarybar"><span>${E6.info?.attached?`<b>${esc(E6.info.path||E6.info.directory||'Local library attached')}</b> · ${E6.info.parts??'?'} parts`: 'Attach a reusable library once; other projects can use it too.'}</span><span class="grow"></span>${button6('engAttach','Attach library')}${button6('engCreate','New library')}</div>`;
 if(E6.tab==='catalog')content+=renderCatalog6();
 if(E6.tab==='reuse')content+=`<section class="panel"><div class="panel-title"><h2>Find candidates for this project</h2>${state6('Screening only','No automatic substitution or qualification.')}</div><div class="panel-body"><p>Recommendations match the resolved value pattern and exact selected footprint, then show rating conflicts, unknowns, catalog preference and dated health. Raw variables remain untouched until a reviewed edit.</p><div class="row">${button6('engSuggest','Choose component…')}${button6('engSuggestSelected','Recommend for selected BOM part')}</div><p class="fine">BOM row actions also expose recommendations. FTS metadata search remains available for exploratory choices outside this compatibility screen.</p><div id="engAutoRecommend" aria-live="polite"></div></div></section>`;
 if(E6.tab==='mass')content+=`<section class="panel"><div class="panel-title"><h2>Fill missing mass—without inventing precision</h2>${state6('Estimated ≠ measured')}</div><div class="panel-body"><p>Exact-MPN catalog observations appear first. Published typical package examples can be offered for supported resistors, MLCCs and a few semiconductor packages. Inspect package height, dielectric and construction assumptions.</p><div class="notice warning">A footprint alone does not establish mass. These are source-linked proposals, not universally correct package constants. Existing nonblank mass fields are never overwritten.</div>${button6('engMass','Find missing-mass suggestions…')}<p class="fine">Acceptance adds Mass_Basis, Mass_Source, Mass_Assumptions and Mass_Uncertainty. Analytics keeps the estimate warning.</p></div></section>`;
 if(E6.tab==='variants')content+=renderVariants6();
 if(E6.tab==='qualify')content+=`<section class="panel"><div class="panel-title"><h2>Declared manufacturer land-pattern checks</h2>${button6('engQualify','Compare geometry & pins…')}</div><div class="panel-body"><p>Compare each numbered pad: position, dimensions, rotation, shape, mounting, layer set, drill and explicitly specified mask/paste details. Pin functions use exact, explicitly accepted names.</p><div class="notice warning">Supply a human-verified transcription of the <b>recommended land pattern</b>, not the component body drawing. Missing checks remain incomplete. No OCR, pin-swap inference, electrical-equivalence claim or manufacturer certification.</div><p class="fine">The same source-linked specification can be stored on a catalog revision. Controlled review binds its report hash, geometry hash, exact MPN and project context.</p></div></section>`;
 if(E6.tab==='reviews')content+=`<section class="panel"><div class="panel-title"><h2>Local authenticated review</h2>${button6('engAccounts','Reviewers & roles')}</div><div class="panel-body"><p>Approvals and waivers name a reviewer, role, reason, evidence reference and expiry. They bind source/workspace state, catalog revisions, geometry and policy. A changed input makes the previous decision stale.</p><div class="notice">Passphrases are local; the first reviewer is an administrator. An administrator creates separate engineering/supply accounts. This is not enterprise identity, PKI or a regulated electronic signature.</div><div class="row">${button6('engReviewPolicy','Review policy…')}${button6('engReviewContext','Assess current approval state')}${button6('engPipelineReview','Export controlled pipeline config')}</div><p class="fine">Errors cannot be waived. Unknown/warning waivers are scoped to one exact finding and require the appropriate role. Locks are editing safeguards, not security boundaries.</p></div></section>`;
 if(E6.tab==='purchasing')content+=`<section class="panel"><div class="panel-title"><h2>Several builds, one inventory ledger</h2>${button6('engBuild','Configure builds & offers…')}</div><div class="panel-body"><p>Pool exact identities across saved projects and variants. Allocate inventory by priority and expiry, account for attrition, MOQ, pack multiples, quantity tiers and typed lead times. Inventory pools are consumed once.</p><div class="row">${button6('engInventory','Inventory lots…')}${button6('engInventoryList','Inspect current inventory')}${button6('engOffers','Prepare offers from catalog evidence')}${button6('engRunBuild','Run saved session scenario')}</div><div class="notice warning">A plan places no orders and reserves no stock. Split orders require explicit permission and review that pools are independent. Different currencies are not silently converted; the priority heuristic is not a global optimum.</div></div></section>`;
 if(E6.tab==='validation')content+=`<section class="panel"><div class="panel-title"><h2>Evidence for the software itself</h2></div><div class="panel-body"><p>Use <code>python cli.py hosttest --directory NEW_DIRECTORY</code> on each actual supported host. It invokes the installed KiCad CLI on a disposable project copy and records the native version, reload and job-set results.</p><div class="notice warning">KiCad-host operation, native libraries, real cross-selection, Windows/macOS installation and assistive screen-reader acceptance are not certified by this package's simulated tests. Absent capabilities stay SKIPPED.</div><p>Use <code>python cli.py benchmark --parts 10000 --queries 100</code> for a reproducible temporary catalog benchmark. Read the included test report for measured results and scope.</p><div class="row">${button6('engVerify','Verify catalog integrity')}${button6('engVirtual','Toggle bounded virtual BOM view')}</div><p class="fine">Catalog search is paginated in SQLite. The optional ungrouped BOM viewport renders a bounded window; the underlying workspace is still loaded in memory. Grouped mode keeps pagination; expanded groups are not virtualized.</p></div></section>`;
 return content+`<div class="spacer"></div>`+reportPanel6();
}
function renderCatalog6(){const page=E6.page;return `<section class="panel"><div class="toolbar"><input id="engQuery" type="search" class="searchbox" value="${esc(E6.query)}" placeholder="Search MPN, value, type, project metadata…" aria-label="Search local catalog"><button class="primary small" data-act="engSearch">Search</button><span class="grow"></span>${button6('engHarvest','Harvest projects…')}${button6('engNewPart','New part')}${button6('engHealth','Catalog health')}${button6('engSnapshot','Export metadata JSON')}${button6('engNative','Export selected native library')}</div><p class="fine eng-pad">Preferences, lifecycle, stock and qualification are separate. Colors always carry text and tooltips. ${page?`${page.total} identities · ${E6.picked.size} selected`: 'Search after attaching a local catalog.'}</p>${page?table6(['Select','Internal PN / revision','Manufacturer / MPN','Value / footprint','Lifecycle','Stock','State','Actions'],page.items.map(p=>`<tr><td><input type="checkbox" data-eng-select="${esc(p.id)}" ${E6.picked.has(p.id)?'checked':''} aria-label="Select ${esc(p.internal_pn||p.id)}"></td><td><b>${esc(p.internal_pn)}</b><br><span class="fine">Revision ${p.revision}</span></td><td>${esc(p.fields.Manufacturer||'Unresolved')}<br><b>${esc(p.fields.MPN||'Generic observation')}</b></td><td>${esc(p.fields.Value)}<br><span class="fine">${esc(p.fields.Footprint)}</span></td><td>${state6(p.health?.lifecycle||'UNKNOWN',p.health?.lifecycle_labels?.join(', '))}</td><td>${state6(p.health?.low_stock?'LOW STOCK < '+p.health.low_stock_threshold:p.health?.stock?.status||'unknown',p.health?.tooltip)}</td><td>${state6(p.status)} ${state6(p.health?.state||'unknown',p.health?.tooltip)}</td><td><div class="row">${button6('engPart','Inspect',`data-id="${esc(p.id)}"`)}${button6('engEditPart','Edit',`data-id="${esc(p.id)}"`)}${button6('engEvidence','Evidence',`data-id="${esc(p.id)}"`)}</div></td></tr>`))+`<div class="table-footer"><span>Rows ${page.offset+1}–${Math.min(page.total,page.offset+page.items.length)} of ${page.total}</span><div class="row">${button6('engPrevious','Previous',!page.offset?'disabled':'')}${button6('engNext','Next',page.next_offset==null?'disabled':'')}</div></div>`:'<div class="empty">Your reusable parts catalog appears here.</div>'}</section>`;}
function renderVariants6(){const all=Object.entries(S.data.variants).filter(([_,v])=>v.bom_only);return `<section class="panel"><div class="panel-title"><h2>Independent BOM variants</h2>${button6('engNewVariant','New BOM-only variant…')}</div><div class="panel-body"><p>Derived variants inherit by design. Pinned variants copy current raw fields, flags and effective variables. They remain independent of native KiCad variant definitions and are excluded from native synchronization.</p><div class="notice">Pinned is not a complete immutable archive: source geometry, hierarchy and supported built-in context can still change. Use a release snapshot and controlled approval for that boundary.</div></div>${table6(['Variant','Parent','Mode','State','Tags','Actions'],all.map(([name,v])=>`<tr><td><b>${esc(name)}</b><br>${esc(v.description)}</td><td>${esc(v.parent)}</td><td>${v.pinned?'Pinned fields':'Derived'}</td><td>${state6(v.locked?'LOCKED':'EDITABLE')}</td><td>${esc((v.tags||[]).join(', '))}</td><td>${button6('engUseVariant','Use',`data-name="${esc(name)}"`)} ${button6('engVariantAction',v.locked?'Unlock / manage…':'Manage…',`data-name="${esc(name)}"`)}</td></tr>`))}</section>`;}
function downloadJSON6(value,name){const url=URL.createObjectURL(new Blob([pretty6(value)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function review6(title,plan,token,apply,extra=''){
 showDialog(title,`<div class="notice warning">Review the full proposed change. This step does not write native KiCad files.</div>${json6(plan)}${button6('engPlanDownload','Download complete plan')}${extra}${field6('Type '+token+' to confirm','confirmation')}${formActions('Stage reviewed change')}`,async f=>{if(f.get('confirmation')!==token)throw Error('Type '+token+' after reviewing.');await apply(f);await refresh();toast('Reviewed operation completed. Native synchronization remains separate.');});E6.pending=plan;
}
async function connect6(create){showDialog(create?'Create a local parts library':'Attach a local parts library',`<p class="fine">Choose an absolute directory on a local disk. A catalog is separate from projects and from KiCad .kicad_sym/.pretty files.</p>${field6('Absolute library directory','path',S.data?.engineering?.library||'')}${create?field6('Type CREATE','confirmation'):''}<label class="check-label"><input type="checkbox" name="remember" checked>Remember as the default for other projects on this computer</label>${formActions(create?'Create library':'Attach library')}`,async f=>{await eng6(create?'create':'attach',{path:f.get('path'),confirmation:f.get('confirmation'),remember:f.has('remember')});E6.info=await eng6('info');E6.page=await eng6('search',{query:'',limit:50});E6.query='';E6.offset=0;await refresh();});}
async function searchCatalog6(){E6.query=$('#engQuery')?.value??E6.query;E6.info=await eng6('info');if(!E6.info.attached)throw Error('Create or attach a local library first.');E6.page=await eng6('search',{query:E6.query,offset:E6.offset,limit:50});render();}
async function editPart6(pid){const part=pid?(await eng6('get',{id:pid})).part:null;showDialog(part?'Edit catalog revision':'New orderable catalog part',`<div class="notice">An existing exact manufacturer/MPN identity cannot be renamed. A preferred part is not automatically qualified.</div><div class="columns2">${field6('Internal part number','ipn',part?.internal_pn||'')}${field6('Manufacturer','manufacturer',part?.fields.Manufacturer||'','text',part?'readonly':'')}${field6('Full orderable MPN','mpn',part?.fields.MPN||'','text',part?'readonly':'')}${field6('Value','value',part?.fields.Value||'')}${field6('Footprint identifier','footprint',part?.fields.Footprint||'')}${field6('Reference/type hint (R1, C1, U1…)','ref',part?.reference_hint||'')}</div><label class="field"><span>Catalog preference</span><select name="status">${['candidate','preferred','deprecated','blocked'].map(x=>`<option ${x===part?.status?'selected':''}>${x}</option>`).join('')}</select></label>${field6('Searchable tags, comma-separated','tags',(part?.tags||[]).join(', '))}${area6('Additional fields JSON (ordinary string properties)','fields',Object.fromEntries(Object.entries(part?.fields||{}).filter(([k])=>!['Manufacturer','MPN','Value','Footprint'].includes(k))),5)}<details><summary>Declared land pattern / candidate alternate links / conflict resolution</summary>${area6('Source-linked wayricad-land-pattern-1 specification, or null','spec',part?.land_pattern||null,5)}${area6('Candidate alternate links JSON (never an approval flag)','alts',part?.alternates||[],4)}${area6('Conflict indexes deliberately resolved in this revision','resolved',[],2)}${part?.conflicts?.length?json6(part.conflicts):''}</details>${field6('Catalog notes','notes',part?.notes||'')}${field6('Editor / actor name','actor')}${field6('Revision reason','reason')}<div class="form-actions"><button type="button" class="primary" id="engPartPreview">Preview revision</button></div>`,()=>{});
 $('#engPartPreview').onclick=async()=>{try{const f=new FormData($('#dialogBody form')),fields={...JSON.parse(f.get('fields')),Manufacturer:f.get('manufacturer'),MPN:f.get('mpn'),Value:f.get('value'),Footprint:f.get('footprint')};const request={...(part?{id:part.id,expected_revision:part.revision}:{new:true}),fields,notes:f.get('notes'),status:f.get('status'),reference_hint:f.get('ref'),tags:String(f.get('tags')).split(',').map(s=>s.trim()).filter(Boolean),land_pattern:JSON.parse(f.get('spec')),alternates:JSON.parse(f.get('alts')),resolve_conflicts:JSON.parse(f.get('resolved'))};if(f.get('ipn'))request.internal_pn=f.get('ipn');const plan=await eng6('part-preview',{request}),actor=f.get('actor'),reason=f.get('reason');review6('Review catalog revision',plan,'CATALOG',async g=>{await eng6('part-apply',{plan,confirmation:g.get('confirmation'),actor,reason});E6.page=await eng6('search',{query:E6.query,offset:E6.offset,limit:50});E6.info=await eng6('info');});}catch(e){toast(e.message,true);}};
}
async function harvest6(){showDialog('Harvest selected local projects',`${area6('Absolute project paths or directories, one per line','paths','',5)}<label class="check-label"><input type="checkbox" name="recursive">Scan subdirectories of the explicitly selected folders</label><label class="check-label"><input type="checkbox" name="assets" checked>Capture resolved embedded symbols and local footprints</label><label class="check-label"><input type="checkbox" name="variants" checked>Include every variant</label><div class="notice">No full-disk scan or network scraping. A completed scan is only a review plan. Existing curated fields win conflicts.</div>${formActions('Scan for review')}`,async f=>{E6.task=await eng6('harvest-start',{paths:String(f.get('paths')).split('\n').map(x=>x.trim()).filter(Boolean),recursive:f.has('recursive'),capture_assets:f.has('assets'),include_variants:f.has('variants')});setTimeout(pollHarvest6,100);});}
async function pollHarvest6(){if(!E6.task)return;try{const t=await eng6('task-status',{id:E6.task.id});E6.task=t;const html=`<div role="status" aria-live="polite"><p>${esc(t.message)}</p><progress max="${t.total||1}" value="${t.current||0}" aria-label="Project scan progress"></progress><p>${t.current||0} / ${t.total||'?'}</p></div>`;if(t.state==='running'){showDialog('Scanning explicit projects',html+`<button type="button" id="engCancelHarvest">Cancel scan</button>`,()=>{});$('#engCancelHarvest').onclick=async()=>{await eng6('task-cancel',{id:t.id});$('#dialog').close();};setTimeout(pollHarvest6,350);}else if(t.state==='ready'){showDialog('Review harvested parts',html+json6(t.summary)+field6('Import actor','actor')+field6('Type IMPORT','confirmation')+`<label class="check-label"><input name="partial" type="checkbox">Import successful projects despite listed failures</label><div class="row">${button6('engHarvestFull','Download complete scan plan')}</div>${formActions('Import into catalog')}`,async f=>{await eng6('harvest-import',{task_id:t.id,confirmation:f.get('confirmation'),actor:f.get('actor'),allow_partial:f.has('partial')});E6.info=await eng6('info');E6.page=await eng6('search',{query:E6.query,limit:50});render();});}else{toast(t.message,t.state==='failed');if($('#dialogTitle').textContent==='Scanning explicit projects')$('#dialog').close();}}catch(e){toast(e.message,true);}}
async function health6(){showDialog('Assess entire matching catalog',`${field6('Search (blank = entire catalog)','query',E6.query)}${field6('Market','market','IN')}${field6('Freshness, hours','freshness_hours','24','number')}${field6('Low-stock warning below quantity','low_stock_threshold','100','number')}<p class="fine">The scan is local, read-only and cancelable. It uses dated observations already recorded in the catalog.</p>${formActions('Run catalog health')}`,async f=>{const t=await eng6('health-start',{query:f.get('query'),market:f.get('market'),freshness_hours:Number(f.get('freshness_hours')),low_stock_threshold:Number(f.get('low_stock_threshold'))});setTimeout(()=>pollHealth6(t.id),100);});}
async function pollHealth6(id){try{const t=await eng6('task-status',{id,include_result:true});if(t.state==='running'){showDialog('Assessing catalog health',`<p role="status">${esc(t.message)} · ${t.current} / ${t.total||'?'}</p><progress max="${t.total||1}" value="${t.current||0}" aria-label="Catalog health progress"></progress><button type="button" id="engCancelHealth">Cancel scan</button>`,()=>{});$('#engCancelHealth').onclick=()=>eng6('task-cancel',{id});setTimeout(()=>pollHealth6(id),300);}else{if($('#dialogTitle').textContent==='Assessing catalog health')$('#dialog').close();if(t.state==='ready')report6(t.result,'Full catalog health · dated observations');else toast(t.message,t.state==='failed');}}catch(e){toast(e.message,true);}}
async function suggestions6(cid){const report=await eng6('recommend',{component:cid,limit:40});E6.lastRecommendations=report;showDialog('Catalog candidates · '+report.component,`<p class="fine">Value pattern and exact footprint are a starting screen. Conflicts block use. Missing ratings, electrical suitability and manufacturer evidence still require engineering review.</p>${table6(['MPN / IPN','Rank','State','Reasons / missing data','Action'],report.items.map(c=>`<tr><td><b>${esc(c.part.fields.MPN)}</b><br>${esc(c.part.internal_pn)}</td><td>${esc(c.score)}</td><td>${state6(c.state,c.health?.tooltip)}</td><td class="wrap">${esc(pretty6({conflicts:c.conflicts,missing:c.missing_evidence,health:c.health?.lifecycle}))}</td><td>${button6('engChooseCandidate','Review use…',`data-component="${esc(cid)}" data-id="${esc(c.part.id)}" ${c.state==='blocked'?'disabled':''}`)}</td></tr>`))}${report.reason?`<p>${esc(report.reason)}</p>`:''}${json6(report)}`,()=>{});}
async function chooseCandidate6(el){const plan=await eng6('recommend-preview',{component:el.dataset.component,part_id:el.dataset.id});review6('Review candidate property edits',plan,'EDIT',async f=>eng6('recommend-apply',{plan,confirmation:f.get('confirmation'),engineering_ack:f.has('engineering'),acknowledge_loss:f.has('loss')}),`<label class="check-label"><input type="checkbox" name="engineering" required>I reviewed compatibility; this only edits metadata, not the library symbol or geometry.</label><label class="check-label"><input type="checkbox" name="loss">Acknowledge any raw-expression loss shown in the plan</label>`);}
