document.addEventListener('keydown',e=>{
 if(!e.target.closest('#engVirtualViewport')||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;
 if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Home','End','PageDown','PageUp'].includes(e.key))return;
 e.preventDefault();e.stopImmediatePropagation();
 const cell=e.target.closest('td[data-field]');let index=cell?virtualRows6.findIndex(r=>r.id===cell.dataset.id):E6.vstart,col=cell?S.columns.indexOf(cell.dataset.field):0;
 if(e.key==='ArrowDown')index++;if(e.key==='ArrowUp')index--;if(e.key==='PageDown')index+=12;if(e.key==='PageUp')index-=12;
 if(e.key==='ArrowLeft')col--;if(e.key==='ArrowRight')col++;if(e.key==='Home'){col=0;if(e.ctrlKey)index=0;}if(e.key==='End'){col=S.columns.length-1;if(e.ctrlKey)index=virtualRows6.length-1;}
 index=Math.min(Math.max(index,0),virtualRows6.length-1);col=Math.min(Math.max(col,0),S.columns.length-1);if(index<0)return;
 const view=$('#engVirtualViewport');virtualWindow6(Math.max(0,index-3));vscroll6=Math.max(0,(index-3)*40);view.scrollTop=vscroll6;
 const target=[...view.querySelectorAll('td[data-id]')].find(x=>x.dataset.id===virtualRows6[index].id&&x.dataset.field===S.columns[col]);if(target){target.tabIndex=0;target.focus({preventScroll:true});}
},true);
// A nonintrusive automatic suggestion cue on a normal BOM row click.
let reuseTimer6;
document.addEventListener('click',e=>{if(S.view!=='bom'||!E6.info?.attached||e.target.closest('button,input,select,textarea'))return;const cell=e.target.closest('td[data-id]');if(!cell)return;const id=cell.dataset.id,seq=++E6.req;clearTimeout(reuseTimer6);reuseTimer6=setTimeout(async()=>{try{const r=await eng6('recommend',{component:id,limit:3});if(seq!==E6.req||S.view!=='bom'||$('#dialog').open)return;$('#reuseCue6')?.remove();const cue=document.createElement('aside');cue.id='reuseCue6';cue.setAttribute('role','status');cue.innerHTML=`<b>${esc(r.component)} · ${r.items.length}${r.items.length===3?'+':''} catalog candidates</b><p>${esc(r.items.map(x=>x.part.fields.MPN).join(' · ')||r.reason||'No matching recorded value and footprint.')}</p>${button6('engSuggestRow','Review candidates',`data-id="${esc(id)}"`)} ${button6('engCloseCue','Dismiss')}`;document.body.append(cue);}catch(_){/* missing/unattached library must not disturb ordinary editing */}},350);});
handlers.engCloseCue=()=>$('#reuseCue6')?.remove();

// Startup moved here so all modules are registered before the first response.
refresh().then(async()=>{if(S.data?.startup_note)toast(S.data.startup_note);try{E6.info=await eng6('info');}catch(_){}const status=await api('link/poll',{});if(status.connected){adoptLink4(status);render();}}).catch(e=>toast(e.message,true));
